import assert from 'node:assert/strict'
import { existsSync } from 'fs'
import { execFileSync } from 'child_process'
import { tmpdir } from 'os'
import { join } from 'path'
import { chromium } from '@playwright/test'
import { installReactiveMic, speakText, speakWav, waitForMicOpen, isNoMic } from './reactive-mic'
import { startElementCapture } from './audio-capture'

// #214: a page with only the synthetic mic (no <audio>) never taps a source, and
// ears.audioClock stayed null on every turn, so a starved audio clock went unseen.
const exe = ['/usr/bin/google-chrome', '/usr/bin/chromium'].find(existsSync)
const browser = await chromium.launch({ headless: true, ...(exe ? { executablePath: exe } : {}), args: ['--autoplay-policy=no-user-gesture-required', '--no-sandbox'] }).catch(() => null)
if (!browser) { console.log('ears clock: skipped (no Chromium)'); process.exit(0) }
try {
  const ctx = await browser.newContext()
  await ctx.addInitScript(() => { (globalThis as any).__name = (globalThis as any).__name || ((f: any) => f) })
  const page = await ctx.newPage()
  await installReactiveMic(page)
  // No mic yet: tagged no_mic error after a short wait, thrown before any synthesis runs
  const bare = await ctx.newPage()
  await installReactiveMic(bare)
  await bare.goto('about:blank')
  let synthesized = false
  const e1: any = await speakText(bare, 'a dynamic microphone test', { onPlayStart: () => { synthesized = true } }).catch((e) => e)
  assert.ok(isNoMic(e1), 'speakText before the mic opens throws the tagged no_mic error')
  assert.equal(synthesized, false, 'it fails before any synthesis')
  const e2: any = await speakWav(bare, '/dev/null').catch((e) => e)
  assert.ok(isNoMic(e2), 'speakWav in-page guard throws the same tagged error')
  assert.equal(isNoMic(new Error('Command failed: espeak-ng ... microphone')), false, 'a message containing "mic" is not no_mic')
  assert.equal(isNoMic(null), false)
  // #468: a ready flag with no audio context is no_mic, not a raw TypeError, and the page's next getUserMedia builds the feed
  const flagged = await ctx.newPage()
  await installReactiveMic(flagged)
  await flagged.route('http://localhost:9/', (r) => r.fulfill({ contentType: 'text/html', body: '<p>no mic</p>' }))
  await flagged.goto('http://localhost:9/')
  await flagged.evaluate(() => { (window as any).__mic.ready = true })
  const e4: any = await speakWav(flagged, '/dev/null').catch((e) => e)
  assert.ok(isNoMic(e4), `a ready flag with no audio context is no_mic (got ${e4?.message})`)
  let flaggedSynth = false
  const e5: any = await speakText(flagged, 'x', { onPlayStart: () => { flaggedSynth = true } }).catch((e) => e)
  assert.ok(isNoMic(e5) && !flaggedSynth, 'speakText on a flag-only page is no_mic from the probe, before any synthesis')
  await flagged.evaluate(() => navigator.mediaDevices.getUserMedia({ audio: true }).then(() => true))
  await waitForMicOpen(flagged, 2000)
  await flagged.close()
  setTimeout(() => { bare.close() }, 300)
  const e3: any = await speakText(bare, 'closed page').catch((e) => e)
  assert.ok(e3 && !isNoMic(e3), 'a page closed during the probe keeps its own error, not no_mic')
  await page.route('http://localhost:9/', (r) => r.fulfill({ contentType: 'text/html', body: '<script>navigator.mediaDevices.getUserMedia({audio:true})</script>' }))
  await page.goto('http://localhost:9/')
  await waitForMicOpen(page)
  await startElementCapture(page)
  const wav = join(tmpdir(), `ears-clock-${process.pid}.wav`)
  execFileSync('ffmpeg', ['-loglevel', 'error', '-y', '-f', 'lavfi', '-i', 'sine=f=300:d=2', '-ar', '24000', wav])
  const { audioMs, playedMs } = await speakWav(page, wav)
  assert.equal(audioMs, 2000, 'speakWav reports the length of the audio it played')
  assert.ok(playedMs >= 1900 && playedMs < 3000, `playing takes as long as the audio (got ${playedMs})`)
  const st = await page.evaluate(() => ({ tapped: !!(globalThis as any).__osbornAudioAnchor, rate: (globalThis as any).__osbornClock.rate() }))
  assert.equal(st.tapped, false, 'no page audio source was tapped')
  assert.ok(st.rate != null && st.rate > 0.8 && st.rate < 1.2, `audioClock reports with no tapped source (got ${st.rate})`)
  console.log('ears clock: all assertions passed')
} finally { await browser.close() }

