/**
 * Unit tests for the pure journey-store logic (#120).
 *   npx tsx --test lib/journey-store.test.ts
 *
 * Covers the two pieces of pure logic the fix hangs on:
 *  - run-id continuity: a journey survives the run-id change across a restart,
 *    carrying previousRun so old → new is explicit (and a second restart chains).
 *  - the transient-502 retry discriminator: an empty gateway 502 (process died)
 *    is retryable; the engine's structured speak_failed/no_mic is NOT.
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import {
  buildJourneyState,
  continuesRecovered,
  decideRecovery,
  isTransientSayFailure,
  retryDelayMs,
  DEFAULT_RECOVERY_MAX_AGE_MS,
  type JourneyStateFile,
  type PersistedJourney,
} from './journey-store.ts'

const j: PersistedJourney = { name: 'break-the-ui', goal: 'exercise voice', owner: 'tester', startUrl: 'https://www.voice-native.com/chat', startedAt: 1_000 }
const active = (updatedAt: number, run = '2026-11-10T16-26-43'): JourneyStateFile =>
  buildJourneyState(run, 'active', j, 3, 3, updatedAt)

test('decideRecovery: no persisted state → no recovery', () => {
  assert.equal(decideRecovery(null, { now: 10_000, currentRun: 'r2' }).recover, false)
  assert.equal(decideRecovery(undefined, { now: 10_000, currentRun: 'r2' }).recover, false)
})

test('decideRecovery: an already-ended journey is not resurrected', () => {
  const ended = buildJourneyState('r1', 'ended', j, 3, 3, 9_000)
  const d = decideRecovery(ended, { now: 10_000, currentRun: 'r2' })
  assert.equal(d.recover, false)
  assert.match(d.reason, /ended/)
})

test('run-id continuity: an active journey is adopted across a run-id change', () => {
  const state = active(9_000, '2026-11-10T16-26-43')      // old process run id
  const d = decideRecovery(state, { now: 10_000, currentRun: '2026-11-10T16-30-39' })
  assert.equal(d.recover, true)
  assert.equal(d.journey?.name, 'break-the-ui')
  // previousRun links the new run back to the one that died mid-journey.
  assert.equal(d.previousRun, '2026-11-10T16-26-43')
})

test('run-id continuity: re-homing chains a second restart to the latest run', () => {
  // First restart adopts under the new run and RE-SAVES with currentRun.
  const first = decideRecovery(active(9_000, 'runA'), { now: 10_000, currentRun: 'runB' })
  assert.equal(first.previousRun, 'runA')
  const resaved = buildJourneyState('runB', 'active', first.journey!, 3, 3, 11_000)
  assert.equal(resaved.run, 'runB')
  // Second restart recovers from runB (one hop back), not the stale runA.
  const second = decideRecovery(resaved, { now: 12_000, currentRun: 'runC' })
  assert.equal(second.recover, true)
  assert.equal(second.previousRun, 'runB')
})

test('decideRecovery: a journey older than the mission cap is dropped', () => {
  const old = active(0)
  const d = decideRecovery(old, { now: DEFAULT_RECOVERY_MAX_AGE_MS + 1, currentRun: 'r2' })
  assert.equal(d.recover, false)
  assert.match(d.reason, /stale/)
})

test('decideRecovery: within the cap is kept, right at the boundary too', () => {
  assert.equal(decideRecovery(active(0), { now: DEFAULT_RECOVERY_MAX_AGE_MS, currentRun: 'r2' }).recover, true)
})

test('decideRecovery: corrupt (future) timestamp is adopted, not dropped', () => {
  const d = decideRecovery(active(10_000), { now: 1_000, currentRun: 'r2' })
  assert.equal(d.recover, true)
  assert.equal(d.ageMs, 0)
})

test('isTransientSayFailure: empty-body gateway 502 (restart) is retryable', () => {
  assert.equal(isTransientSayFailure(502, ''), true)
  assert.equal(isTransientSayFailure(502, null), true)
  assert.equal(isTransientSayFailure(502, {}), true)
  assert.equal(isTransientSayFailure(503, '   '), true)
  assert.equal(isTransientSayFailure(504, undefined), true)
})

test('isTransientSayFailure: a non-JSON gateway page is retryable', () => {
  assert.equal(isTransientSayFailure(502, '<html>502 Bad Gateway</html>'), true)
})

test('isTransientSayFailure: no HTTP status (socket reset) is retryable', () => {
  assert.equal(isTransientSayFailure(0, ''), true)
  assert.equal(isTransientSayFailure(undefined, null), true)
  assert.equal(isTransientSayFailure(NaN, null), true)
})

test('isTransientSayFailure: the engine structured speak_failed 502 is NOT retried', () => {
  assert.equal(isTransientSayFailure(502, { ok: false, code: 'speak_failed', error: 'could not speak' }), false)
  assert.equal(isTransientSayFailure(502, JSON.stringify({ ok: false, code: 'speak_failed' })), false)
})

test('isTransientSayFailure: no_mic (422) and success (200) are NOT retried', () => {
  assert.equal(isTransientSayFailure(422, { ok: false, code: 'no_mic' }), false)
  assert.equal(isTransientSayFailure(200, { ok: true }), false)
  assert.equal(isTransientSayFailure(400, { error: 'bad' }), false)
})

test('retryDelayMs: bounded exponential backoff', () => {
  assert.equal(retryDelayMs(1), 1000)
  assert.equal(retryDelayMs(2), 2000)
  assert.equal(retryDelayMs(3), 4000)
  assert.equal(retryDelayMs(10), 8000)   // capped
  assert.ok(retryDelayMs(2) >= retryDelayMs(1))
})

test('#171: only the owner from before the restart continues the recovered journey, by name', () => {
  const recovered = { name: 'pr156-retest', recovered: true, recoveredOwner: 'agent-a' }
  assert.equal(continuesRecovered(recovered, 'pr156-retest', 'agent-a'), true)
  assert.equal(continuesRecovered(recovered, 'pr156-retest', ' agent-a '), true)  // canonical spelling
  assert.equal(continuesRecovered(recovered, 'pr156-retest', 'agent-b'), false)   // same name, another driver
  assert.equal(continuesRecovered(recovered, 'pr156-retest', 'person:a@x.com'), false)
  assert.equal(continuesRecovered(recovered, 'another', 'agent-a'), false)
  assert.equal(continuesRecovered({ ...recovered, owner: 'agent-a' }, 'pr156-retest', 'agent-a'), false)  // already re-claimed
  assert.equal(continuesRecovered({ name: 'pr156-retest', owner: 'agent-a' }, 'pr156-retest', 'agent-a'), false)  // a live journey
  assert.equal(continuesRecovered(null, 'pr156-retest', 'agent-a'), false)
})

test('#171: a person continues only their own recovered journey, compared canonically', () => {
  const mine = { name: 'j', recovered: true, recoveredOwner: 'person:a@x.com' }
  assert.equal(continuesRecovered(mine, 'j', 'person:A@X.com'), true)
  assert.equal(continuesRecovered(mine, 'j', 'person:b@x.com'), false)
  // An ownerless recovered journey (an older record): agents may continue it, a person never.
  const ownerless = { name: 'j', recovered: true }
  assert.equal(continuesRecovered(ownerless, 'j', 'agent-a'), true)
  assert.equal(continuesRecovered(ownerless, 'j', 'person:a@x.com'), false)
})

test('#171: a start with no name never continues a recovered journey', () => {
  const unnamed = { name: 'unnamed', recovered: true, recoveredOwner: 'agent-a' }
  assert.equal(continuesRecovered(unnamed, undefined, 'agent-a'), false)
  assert.equal(continuesRecovered(unnamed, '', 'agent-a'), false)
  assert.equal(continuesRecovered(unnamed, 'unnamed', 'agent-a'), true)  // only when named explicitly
})

files.lib/journey-store.ts:
/**
 * JOURNEY STORE — durable journey/run state so a mid-journey engine RESTART
 * does not silently lose the journey (#120).
 *
 * Background (#120): the engine's `journey` object and its `RUN_STAMP` run id
 * live ONLY in process memory. A restart — crash / OOM / Fly machine recycle,
 * observed most visibly at the Say step, where Fly's edge proxy returns an
 * EMPTY 502 as the dying process drops the connection — starts a fresh process
 * that re-stamps the run id and reconstructs `journey` as null. The caller then
 * reads `/status` → journey null, tabs reset, taskCount 0, and `/journey end`
 * → 400 "no journey in progress". The restart is silent and destructive.
 *
 * This module persists the active journey to a VOLUME-DURABLE file (the same
 * durability guarantee the engine already relies on for tab-state restore
 * across sleep) and decides, on the next boot, whether a persisted journey
 * should be ADOPTED by the new process — turning a silent, destructive restart
 * into a visible, recoverable one that keeps run-id continuity (previousRun).
 *
 * DESIGN: this file imports only the pure driver rules. All logic here is pure and
 * synchronously testable (no fs, no browser, no volume) — the thin file I/O
 * wrappers live in session-engine.ts, which already imports `fs`. Keeping the
 * decision logic pure is what lets the unit tests cover run-id continuity and
 * the transient-502 retry discriminator without standing up an engine.
 */

import { canonicalDriverId, isPersonDriver, personOwns } from './event-scope'

/** The in-memory journey shape the engine owns, trimmed to what survives a restart. */
export interface PersistedJourney {
  name: string
  goal?: string
  owner?: string
  startUrl: string
  startedAt: number
  /** Scenario steps done in this journey before the restart. */
  steps?: Array<{ kind: string; value: string }>
}

/** The on-disk journey-state record (journey-state.json in the results dir). */
export interface JourneyStateFile {
  schema: 1
  /** The RUN_STAMP of the process that last wrote this record. */
  run: string
  /** 'active' while a journey is in progress; 'ended' after /journey end. */
  status: 'active' | 'ended'
  journey: PersistedJourney
  /** Progress markers so a recovered journey can point a caller at prior work. */
  lastTaskN: number
  tasksStamped: number
  updatedAt: number
}

export interface RecoveryOptions {
  now: number
  /** The NEW process's run id — recorded so continuity (old → new) is explicit. */
  currentRun: string
  /**
   * Don't resurrect a journey older than this. Defaults to the engine's mission
   * cap (2h) so recovery never outlives the idle-stop hold-awake window.
   */
  maxAgeMs?: number
}

export interface RecoveryDecision {
  recover: boolean
  reason: string
  journey?: PersistedJourney
  /** The run id the journey was last persisted under (for previousRun linkage). */
  previousRun?: string
  ageMs?: number
}

/** The engine's mission cap (2h) — a recovered journey older than this is dropped. */
export const DEFAULT_RECOVERY_MAX_AGE_MS = 2 * 60 * 60 * 1000

/**
 * Build the on-disk record for the CURRENT process. `run` is always the new
 * process's run id, so each save re-homes the journey under the live run —
 * that is the run-id continuity chain (a second restart recovers from the most
 * recent run, with previousRun pointing one hop back).
 */
export function buildJourneyState(
  run: string,
  status: 'active' | 'ended',
  journey: PersistedJourney,
  lastTaskN: number,
  tasksStamped: number,
  now: number,
): JourneyStateFile {
  return { schema: 1, run, status, journey, lastTaskN, tasksStamped, updatedAt: now }
}

/**
 * Decide, on boot, whether a persisted journey should be adopted by the new
 * process. Recover only an ACTIVE journey that is still within the age cap;
 * an already-ended or stale record is ignored (a fresh start proceeds normally).
 */
export function decideRecovery(
  persisted: JourneyStateFile | null | undefined,
  opts: RecoveryOptions,
): RecoveryDecision {
  const maxAgeMs = opts.maxAgeMs ?? DEFAULT_RECOVERY_MAX_AGE_MS
  if (!persisted || persisted.schema !== 1 || !persisted.journey) {
    return { recover: false, reason: 'no persisted journey' }
  }
  if (persisted.status !== 'active') {
    return { recover: false, reason: 'journey already ended' }
  }
  const ageMs = opts.now - persisted.updatedAt
  if (!(ageMs >= 0)) {
    // Clock skew / corrupt timestamp — treat as fresh (age 0) rather than drop.
    return { recover: true, reason: 'active journey (clock skew — adopting)', journey: persisted.journey, previousRun: persisted.run, ageMs: 0 }
  }
  if (ageMs > maxAgeMs) {
    return { recover: false, reason: `stale — ${Math.round(ageMs / 60000)}min old, past the ${Math.round(maxAgeMs / 60000)}min cap`, ageMs }
  }
  return { recover: true, reason: 'active journey within cap — adopting across restart', journey: persisted.journey, previousRun: persisted.run, ageMs }
}

/**
 * A recovered journey has no owner (the mission lock is dropped), so nothing
 * stops a `/journey start` from replacing it and its steps (#171). A start by
 * the driver who owned it before the restart, with the journey's own name, is
 * that driver re-attaching: it continues the journey, steps and all. Anyone
 * else, or a start with no name, gets a fresh journey as before. A person
 * continues only a journey they owned (personOwns), never an ownerless one.
 */
export function continuesRecovered(
  current: { name: string; owner?: string; recovered?: boolean; recoveredOwner?: string } | null | undefined,
  startName: unknown,
  startOwner: string,
): boolean {
  if (!current?.recovered || current.owner || typeof startName !== 'string' || !startName || current.name !== startName) return false
  const was = current.recoveredOwner ? canonicalDriverId(current.recoveredOwner) : undefined
  const me = canonicalDriverId(startOwner)
  return isPersonDriver(me) ? personOwns(was, me) : !was || was === me
}

/**
 * RETRY DISCRIMINATOR for the Say step (#120). Distinguish a TRANSIENT gateway
 * failure (the engine process dropped the connection mid-request — Fly returns
 * an empty-body 502/503/504, or the socket resets with no HTTP status) from an
 * APPLICATION failure that the engine itself reported with a structured body
 * (e.g. { ok:false, code:'speak_failed' } or 'no_mic'). Only the former is
 * worth retrying / re-attaching; retrying a structured app error just repeats a
 * settled failure (the engine already retries the in-page speak internally).
 *
 * @param status HTTP status (0/NaN/undefined = no response / connection reset)
 * @param body   parsed JSON body if any, else the raw string, else null
 */
export function isTransientSayFailure(status: number | undefined | null, body: unknown): boolean {
  // No HTTP status at all → socket reset / connection refused → transient.
  if (status == null || Number.isNaN(status) || status === 0) return true
  if (status !== 502 && status !== 503 && status !== 504) return false
  // A gateway status WITH the engine's structured error is still an app failure
  // the engine chose to surface (speak_failed / no_mic) — do not retry.
  if (body && typeof body === 'object') {
    const b = body as Record<string, unknown>
    if (b.ok === false && typeof b.code === 'string') return false
    // Any other non-empty JSON object from the engine → treat as app response.
    if (Object.keys(b).length > 0) return false
  }
  if (typeof body === 'string' && body.trim().length > 0) {
    // A non-JSON gateway page ("502 Bad Gateway") is the restart signature.
    try {
      const parsed = JSON.parse(body) as Record<string, unknown>
      if (parsed && parsed.ok === false && typeof parsed.code === 'string') return false
      if (parsed && Object.keys(parsed).length > 0) return false
    } catch {
      // Not JSON → gateway/empty-ish body → transient.
    }
  }
  return true
}

/**
 * Bounded exponential backoff for the in-process Say retry: base * 2^(n-1),
 * capped. (The caller-side re-attach after a full restart polls /status for the
 * engine to wake; this delay is for transient in-process speak glitches.)
 */
export function retryDelayMs(attempt: number, baseMs = 1000, capMs = 8000): number {
  if (attempt <= 1) return baseMs
  return Math.min(capMs, baseMs * Math.pow(2, attempt - 1))
}

