/**
 * Programmatic test-user login — no UI, no OAuth wall, no Mac needed.
 *
 * Signs in via Supabase's password grant (the test user created server-side,
 * routed to the main account's machine), then writes the session as the
 * @supabase/ssr cookie format into profiles/osbornojure/state.json — the
 * storageState every `profile: osbornojure` scenario already uses. Re-run
 * any time the session expires.
 *
 *   npx tsx scripts/login-test-user.ts
 */
import { readFileSync, writeFileSync, mkdirSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
// Frontend env resolved relative to the repo (override: OSBORN_FRONTEND_ENV_FILE)
// — no machine-specific absolute paths in the harness.
const FE_ENV_PATH = process.env.OSBORN_FRONTEND_ENV_FILE || join(__dirname, '..', '..', '..', 'frontend', '.env.local')
const feEnv = readFileSync(FE_ENV_PATH, 'utf8')
const SUPABASE_URL = feEnv.match(/^NEXT_PUBLIC_SUPABASE_URL=(\S+)/m)![1]
const ANON = feEnv.match(/^NEXT_PUBLIC_SUPABASE_ANON_KEY=(\S+)/m)![1]
const creds = readFileSync(join(__dirname, '..', 'profiles', 'test-user.env'), 'utf8')
const EMAIL = creds.match(/^TEST_USER_EMAIL=(\S+)/m)![1]
const PASSWORD = creds.match(/^TEST_USER_PASSWORD=(\S+)/m)![1]
const REF = new URL(SUPABASE_URL).hostname.split('.')[0]
const APP_HOST = new URL(process.env.OSBORN_APP_URL || 'https://www.voice-native.com').hostname

const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
  method: 'POST',
  headers: { apikey: ANON, 'Content-Type': 'application/json' },
  body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
})
if (!res.ok) throw new Error(`login failed ${res.status}: ${await res.text()}`)
const session = await res.json()
console.log(`✅ signed in as ${session.user?.email} (expires in ${session.expires_in}s)`)

// @supabase/ssr cookie format: sb-<ref>-auth-token = "base64-" + base64url(JSON),
// chunked into name.0, name.1... when longer than ~3180 chars.
const raw = 'base64-' + Buffer.from(JSON.stringify(session)).toString('base64url')
const CHUNK = 3180
const name = `sb-${REF}-auth-token`
const cookies: any[] = []
if (raw.length <= CHUNK) {
  cookies.push({ name, value: raw })
} else {
  for (let i = 0; i * CHUNK < raw.length; i++)
    cookies.push({ name: `${name}.${i}`, value: raw.slice(i * CHUNK, (i + 1) * CHUNK) })
}
const state = {
  cookies: cookies.map((c) => ({
    ...c,
    domain: APP_HOST,
    path: '/',
    expires: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7,
    httpOnly: false,
    secure: true,
    sameSite: 'Lax',
  })),
  origins: [
    {
      origin: `https://${APP_HOST}`,
      localStorage: [
        // Land in cloud mode from first paint — fresh profiles default to
        // 'local', which probes localhost:8741, shows "Local (offline)", and
        // hides the account's real machine + recent conversations entirely
        // (observed: logged-in dashboard looked logged-out).
        { name: 'osborn-connection-mode', value: 'cloud' },
      ],
    },
  ],
}
// Which profile dir to write. Defaults to osborn-tester (the email/password
// test account in profiles/test-user.env — the only kind this password-grant
// flow can mint; Google-OAuth accounts like ozyjunks cannot be logged in
// headlessly). See session-engine OSBORN_TEST_PROFILE.
const profileName = process.env.OSBORN_TEST_PROFILE || 'osborn-tester'
const out = join(__dirname, '..', 'profiles', profileName, 'state.json')
mkdirSync(dirname(out), { recursive: true })
writeFileSync(out, JSON.stringify(state, null, 2))
console.log(`✅ storageState for '${profileName}' (${session.user?.email}) written to ${out} (${cookies.length} cookie chunk(s))`)

files.scripts/session-engine.ts:
/**
 * SESSION ENGINE — a persistent, director-controlled browser session.
 *
 * The self-hostable core of the Browser Screen Recorder skill: launch ONE
 * browser and KEEP IT ALIVE, streaming live, holding its room connection,
 * waiting for commands. The director (a supervising agent or the user via
 * curl) drives it step by step and reads state between actions. Runs the same
 * on a laptop (headed Chrome) or any container/Fly machine (bundled headless
 * Chromium) — and the brain attaches over CDP, so a cloud browser vendor
 * (Browserbase etc.) can substitute for the local launch.
 *
 *   npx tsx scripts/session-engine.ts
 *
 * Control over HTTP (default :8781; live MJPEG viewer on :8080). When
 * OSBORN_ENGINE_TOKEN is set (ALWAYS set it on public deployments), every
 * request must carry `x-engine-token: <token>`.
 *   GET  /status              → ground truth: pageUrl, pageState, idlePaused,
 *                               brain ready/dead, lastFrameAgeMs, runDir,
 *                               ears (recording age vs decode cap), capturePaused
 *   GET  /tasks               → this run's task index (from the manifest)
 *   GET  /clip?n=N            → download task N's mp4 (video/mp4)
 *   GET  /artifact?n=N        → download task N's screenshot (image/jpeg)
 *   POST /act    {instruction}→ brain acts (Stagehand, cached). Returns clip.
 *   POST /say    {text}       → speak into the mic. Returns clip + heard reply.
 *   POST /hear   {lastMs}     → transcript of what the agent said recently
 *   POST /shot                → screenshot evidence link (base64 with inline:true;
 *                               an on-demand look, NOT the per-task proof — video is)
 *   POST /tab    {op,url,i}   → open | switch | list tabs
 *   POST /brain               → re-init a detached Stagehand brain in place
 *   POST /recover             → reload the active tab (unstick a blank page)
 *   POST /end                 → graceful leave + save audio + shut down (bounded)
 *
 * RESULTS MODEL (v2): every engine run gets its own folder
 *   <results>/runs/<stamp>/   (results dir: OSBORN_RESULTS_DIR or
 *                              test-results/session-engine — on Fly point it
 *                              at the /data volume)
 * VIDEO IS THE PROOF MEDIUM (user decision 2026-07-31): every /act and /say
 * returns its own mp4 clip from the live-stream ring buffer, delivered PER
 * TASK — never batched to run end. No per-task screenshots. manifest.json is
 * REWRITTEN ON EVERY EVENT — kill the engine at any point and the full task
 * index is already on disk. No continuous recordVideo (the old model grew
 * 1.3GB in 3 days and its index only wrote on a clean /end). Old runs are
 * pruned at startup (keep OSBORN_KEEP_RUNS, default 30).
 *
 * TWO MODES:
 *  - DIRECTED: the user/agent drives via /act & /say, video proof per task.
 *  - SELF-DRIVING (replay): every directed /act and /say also appends to this
 *    run's scenario.yaml (same shape as scenarios/*.yaml). Copy it into
 *    scenarios/ to canonize a workflow; the step-cache + knowledge/<site>/
 *    files are the per-site step memory that makes replays cheap (cache HIT =
 *    0 LLM calls) and self-healing on drift.
 *
 * Auth flow by default (profiles/<OSBORN_TEST_PROFILE>, default osborn-tester)
 * when a saved profile exists; guest link if not.
 */
import { chromium, devices, type Browser, type BrowserContext, type Page } from '@playwright/test'
import { Stagehand } from '@browserbasehq/stagehand'
import { createServer } from 'http'
import { execFile } from 'child_process'
import { createHash, createHmac, randomBytes } from 'crypto'
import { promisify } from 'util'
import { existsSync, mkdirSync, writeFileSync, readFileSync, readdirSync, rmSync, createReadStream, statSync, renameSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'
import { freemem } from 'os'
import { installReactiveMic, speakText, warmUpSpeech, isNoMic } from '../lib/reactive-mic'
import { installActionVisualizer } from '../lib/action-visualizer'
import { startLiveStream } from '../lib/live-stream'
import { pickGeminiModel } from '../lib/brain-model'
import { artifactMissing } from '../lib/artifact-missing'
import { saveCapture, peekCapture, startElementCapture, installPageAudioTap, recordingMsAt, AUDIO_DECODE_CAP_MS, decodeBudgetMs, recordingAge, type AudioClock } from '../lib/audio-capture'
import { enterFreshRoom, ensureSessionLive } from '../lib/steps'
import { hearSince, hearFromWav } from '../lib/converse'
import { shouldRetryWithVision, summarizeVision, VISION_MAX_STEPS, viewportMatches, visionGate, visionInstruction } from '../lib/vision-retry'
import { metricsDelta, NO_USAGE, readTotals, type ActUsage, type MetricsTotals } from '../lib/brain-metrics'
import { actWithCache, brainPageFor, BRAIN_GONE, fencedCall, forgetCached, withTimeout, zombieGate } from '../lib/step-cache'
import { openTab, switchTab, closeTab, ownDefaultTab } from '../lib/tabs'
import { serialSaver, writeAtomic } from '../lib/profile-save'
import { attachDevtools, redactDiagnostics, redactJson, type DevtoolsBuffer } from '../lib/devtools'
import { saveJourney, listJourneys } from '../lib/knowledge'
import { mintProfileFromEnv } from '../lib/mint-profile'
import { optionalEnvKey } from '../lib/env'
import { canonicalDriverId, eventOwners, eventVisibleTo, isPersonDriver, ownerSeenBy, personMayTake, personOwns, seesTabOf, tabsFor } from '../lib/event-scope'
import { buildJourneyState, continuesRecovered, decideRecovery, retryDelayMs, type JourneyStateFile, type PersistedJourney } from '../lib/journey-store'

const __dirname = dirname(fileURLToPath(import.meta.url))
const execFileP = promisify(execFile)
// Agent URL = the Voice Native machine the auto-joined chat talks to. NO
// hardcoded default (#49): the old default host (osborn-1b9d70e5-v2.fly.dev)
// left DNS when that agent machine was retired, and a dead default just wedges
// the boot chat on "Connecting…" forever. Empty = no agent configured → the
// engine skips the room join, opens a neutral page, and marks `agentUnreachable`
// on /status + the live view. Set OSBORN_AGENT_URL to a reachable agent to
// auto-join a chat.
const AGENT_URL = process.env.OSBORN_AGENT_URL || ''
const APP_URL = process.env.OSBORN_APP_URL || 'https://www.voice-native.com'
const CONTROL_PORT = Number(process.env.SESSION_ENGINE_PORT ?? 8781)
const CDP_PORT = 9280
const OUT_DIR = process.env.OSBORN_RESULTS_DIR || join(__dirname, '..', 'test-results', 'session-engine')
const RUNS_ROOT = join(OUT_DIR, 'runs')
const RUN_STAMP = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
// Which build is answering (#172): the commit baked in at deploy, the skill
// version it ships, and when this process started.
const ENGINE_BUILD = {
  commit: process.env.HARNESS_SHA || 'dev',
  skillVersion: (() => { try { return readFileSync(join(__dirname, '..', 'SKILL.served.md'), 'utf8').match(/^Version: (\d+)/m)?.[1] ?? null } catch { return null } })(),
  startedAt: new Date().toISOString(),
}
const RUN_DIR = join(RUNS_ROOT, RUN_STAMP)
mkdirSync(RUN_DIR, { recursive: true })

// Retention: keep the newest OSBORN_KEEP_RUNS run folders (counting this one),
// prune the rest at startup so the artifact dir can't balloon.
const KEEP_RUNS = Number(process.env.OSBORN_KEEP_RUNS ?? 30)
try {
  const old = readdirSync(RUNS_ROOT).filter((d) => d !== RUN_STAMP).sort()
  for (const d of old.slice(0, Math.max(0, old.length - (KEEP_RUNS - 1))))
    rmSync(join(RUNS_ROOT, d), { recursive: true, force: true })
} catch { /* first run */ }

// INCREMENTAL MANIFEST — the crash-proof task index. Rewritten on every mark
// and every task stamp; there is no end-of-run-only write anywhere.
const marks: { t: number; mark: string }[] = []
const tasks: Array<{ n: number; label: string; text?: string; heard?: string; startMs: number; endMs: number; rel0: number; rel1: number; clip?: string | null }> = []
const manifest: Record<string, unknown> = {
  run: RUN_STAMP, startedAt: Date.now(), model: 'per-task video + incremental manifest (v2)',
  agentUrl: AGENT_URL, appUrl: APP_URL, profile: null, useAuth: false, live: null,
  tasks, endedAt: null, audioCapture: null,
  // #120: when this process ADOPTED a journey from a process that died
  // mid-journey, this links back to the run that died (else null). Lets a
  // caller pull the pre-restart run's media via /clip?run=<previousRun>.
  previousRun: null,
}
const writeManifest = () => {
  try { writeFileSync(join(RUN_DIR, 'manifest.json'), redactJson({ ...manifest, marks: marks.slice(-200) }, 2)) } catch { /* ignore */ }
}
const mark = (m: string) => { marks.push({ t: Date.now(), mark: m }); writeManifest(); console.log(`[engine] ${m}`) }

// MODE-2 STEP MEMORY: every directed /act and /say also lands in this run's
// scenario.yaml (same shape as scenarios/*.yaml) — a directed session becomes
// a replayable workflow. Copy into scenarios/ to canonize.
const scenarioSteps: Array<{ kind: string; value: string }> = []
const writeScenario = () => {
  try {
    const y = [
      `name: run-${RUN_STAMP}`,
      `description: Auto-exported from a directed engine session (${RUN_STAMP}).`,
      `profile: ${manifest.profile ?? 'osborn-tester'}`,
      'steps:',
      ...scenarioSteps.map((s) => `  - ${s.kind}: ${redactJson(s.value)}`),
    ].join('\n')
    writeFileSync(join(RUN_DIR, 'scenario.yaml'), y + '\n')
  } catch { /* ignore */ }
}

// LAST-RESORT SAFETY NET: one stray rejection (a model API error surfacing from
// inside the brain library, a CDP call on a closed tab) must never take down
// the engine every driver shares. Log it, mark it, keep serving.
process.on('unhandledRejection', (e) => { mark(`unhandled rejection (engine kept alive): ${String((e as Error)?.message ?? e).slice(0, 160)}`) })
// A synchronous throw leaves the process in an unknown state: exit, so the
// machine restarts on the next request instead of answering as a zombie.
process.on('uncaughtException', (e) => { mark(`uncaught exception — exiting: ${String(e?.message ?? e).slice(0, 160)}`); writeManifest(); process.exit(1) })

async function main() {
  // Which voice-native test account the engine drives. Default osborn-tester
  // (osborn-tester@voice-native.com — the email/password account, so its
  // profile is script-mintable via scripts/login-test-user.ts) so the engine's
  // meeting/session doesn't collide with your own osbornojure usage. NOTE:
  // ozyjunks@gmail.com is Google-OAuth and can NEVER be minted headlessly.
  // Override with OSBORN_TEST_PROFILE. If no saved profile exists for it, the
  // engine falls back to the guest link (works, but not the real auth path).
  const profileName = process.env.OSBORN_TEST_PROFILE || 'osborn-tester'
  const profile = join(__dirname, '..', 'profiles', profileName, 'state.json')
  // Cloud auth: no profile on disk (images ship guest-only) but operator
  // provided creds via secrets → mint a fresh session right now. Runs every
  // boot, so the ~1h Supabase session is always fresh after a wake.
  if (!existsSync(profile)) await mintProfileFromEnv(profile, APP_URL)
  const useAuth = existsSync(profile)
  manifest.profile = profileName; manifest.useAuth = useAuth
  mark(`test account: ${profileName} (${useAuth ? 'auth profile found' : 'no profile → guest link'})`)
  // Launch modes:
  //  - Local Mac: real Chrome, headed (you see the real window yourself).
  //  - Container + OSBORN_DISPLAY (Xvfb running, set by fly-run.sh): bundled
  //    Chromium HEADFUL on the virtual display — the x11grab stream then shows
  //    the FULL browser (real tab strip, URL bar, navigation).
  //  - Container without a display: headless fallback (CDP capture + HUD).
  const IN_CONTAINER = !!process.env.OSBORN_TEST_CONTAINER
  const DISPLAY_MODE = !!process.env.OSBORN_DISPLAY
  // Recording the whole window (tab strip and address bar) is opt-in; see live-stream.ts.
  const FULL_WINDOW = DISPLAY_MODE && process.env.OSBORN_CAPTURE === 'display'
  // Display mode: start the stream server BEFORE the browser — a wake-up
  // visitor gets the viewer page in seconds and watches Chrome itself boot.
  let live: Awaited<ReturnType<typeof startLiveStream>> | null = null
  if (FULL_WINDOW) live = await startLiveStream(null).catch(() => null)
  const launchArgs = ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream',
    '--autoplay-policy=no-user-gesture-required', `--remote-debugging-port=${CDP_PORT}`]
  if (IN_CONTAINER) launchArgs.push('--no-sandbox') // container runs as root
  if (DISPLAY_MODE) launchArgs.push('--window-position=0,0', `--window-size=${(process.env.OSBORN_DISPLAY_SIZE || '1280x800').replace('x', ',')}`)
  // DevTools ON CAMERA: OSBORN_DEVTOOLS=1 auto-opens the DevTools panel for
  // every tab — console/network visible in the stream and clips.
  if (process.env.OSBORN_DEVTOOLS) launchArgs.push('--auto-open-devtools-for-tabs')
  // OSBORN_CHROMIUM_PATH: use an existing Chromium/Chrome binary instead of
  // Playwright's own download — for hosts whose preinstalled browser doesn't
  // match this package's pinned Playwright build ("Executable doesn't exist").
  const CHROMIUM_PATH = process.env.OSBORN_CHROMIUM_PATH || null
  const browser: Browser = await chromium.launch({
    ...(CHROMIUM_PATH ? { executablePath: CHROMIUM_PATH, headless: IN_CONTAINER ? !DISPLAY_MODE : false }
      : IN_CONTAINER ? { headless: !DISPLAY_MODE } : { channel: 'chrome', headless: false }),
    args: launchArgs,
  })
  // The shared profile's own saved sign-ins (see PROFILES below) win over the boot profile.
  // A freshly minted/re-run boot profile is newer and wins; a bad saved file is moved aside.
  const SHARED_PROFILE = join(OUT_DIR, 'profiles', 'shared.json')
  const sharedState = existsSync(SHARED_PROFILE) && (!useAuth || statSync(SHARED_PROFILE).mtimeMs > statSync(profile).mtimeMs)
    ? SHARED_PROFILE : useAuth ? profile : undefined
  // A saved profile file that cannot be read is moved aside (`.bad`) and the context opens with `fallback`.
  const openSaved = <S>(open: (s?: S) => Promise<BrowserContext>, state: S | undefined, file: string, fallback?: S): Promise<BrowserContext> =>
    open(state).catch(async (e) => {
      if (state !== file) throw e
      try { renameSync(file, `${file}.bad`) } catch { /* ignore */ }
      mark(`saved profile unreadable (${(e as Error).message.slice(0, 80)}) — moved aside`)
      return open(fallback)
    })
  const newShared = (state?: string) => browser.newContext({ permissions: ['microphone'], ...(state ? { storageState: state } : {}) })
  const context: BrowserContext = await openSaved(newShared, sharedState, SHARED_PROFILE, useAuth ? profile : undefined)
  // NO recordVideo — per-task clips from the live-stream ring buffer are
  // the video record (the continuous recording grew unbounded).
  // tsx/esbuild injects a __name helper that isn't defined in the browser's
  // evaluate context. CONTEXT-level so EVERY page gets it — page-level missed
  // tabs opened later (caught live by the devtools sense: "__name is not
  // defined" pageerror on tab 1's HUD evaluate).
  const prepareContext = async (c: BrowserContext) => {
    await c.addInitScript(() => { (globalThis as any).__name = (globalThis as any).__name || ((f: any) => f) })
    // Lets a page know it is inside the engine (the in-app Browser hides its own live view there).
    await c.addInitScript(() => { (globalThis as any).__osbornEngine = true })
    await installPageAudioTap(c)  // every tab and popup: WebAudio output reaches the ears
  }
  await prepareContext(context)
  // PROFILES: each person (the /browser panel's signed-in user) or agent that names
  // one (`x-profile`) gets its own Chrome profile — cookies and sign-ins isolated
  // from everyone else's and saved to the volume, so they survive restarts. No
  // profile = the shared one, as before. Tabs keep ONE index space across profiles,
  // in the order they were opened, so existing callers' tab numbers still hold.
  const PROFILES_DIR = join(OUT_DIR, 'profiles')
  mkdirSync(PROFILES_DIR, { recursive: true })
  const contexts = new Map<string, BrowserContext>([['', context]])
  const tabOrder: Page[] = []
  const pageProfile = new WeakMap<Page, string>()
  const trackContext = (c: BrowserContext, key: string) => c.on('page', (p) => {
    tabOrder.push(p); pageProfile.set(p, key)
    p.once('close', () => { const i = tabOrder.indexOf(p); if (i >= 0) tabOrder.splice(i, 1) })
  })
  trackContext(context, '')
  const allPages = () => tabOrder.filter((p) => !p.isClosed())
  const tabs = { pages: allPages } as unknown as BrowserContext  // the tab helpers only read pages()
  const profileFile = (key: string) => key ? join(PROFILES_DIR, `${createHash('sha256').update(key).digest('hex').slice(0, 20)}.json`) : SHARED_PROFILE
  // DEVICE EMULATION: /tab open with viewport "mobile" | "tablet" puts the tab in its own
  // context built from a Playwright device descriptor (touch, mobile user agent, device
  // pixel ratio, isMobile), so (hover:none) and (pointer:coarse) match. It starts with the
  // profile's current sign-ins; one context per profile and device, closed with its last
  // tab so its memory goes back. Sign-ins made inside it are not saved back to the profile.
  const DEVICE_PRESETS = { mobile: 'iPhone 13', tablet: 'iPad (gen 7)' } as const
  type DeviceKind = keyof typeof DEVICE_PRESETS
  const isDeviceKind = (v: unknown): v is DeviceKind => typeof v === 'string' && Object.hasOwn(DEVICE_PRESETS, v)
  const deviceContexts = new Map<string, BrowserContext>()
  const pageDevice = new WeakMap<Page, DeviceKind>()
  const deviceOf = (p: Page) => { const d = pageDevice.get(p); return d ? { device: d, emulates: DEVICE_PRESETS[d] } : {} }
  const contextFor = async (key: string, device?: DeviceKind): Promise<BrowserContext> => {
    const id = device ? `${key}\n${device}` : key
    const owned = device ? deviceContexts : contexts
    const have = owned.get(id)
    if (have) return have
    const file = profileFile(key)
    // A device context copies the profile's live sign-ins, or its saved file when no desktop tab has opened it.
    const signedIn = device ? contexts.get(key) : undefined
    const state = signedIn ? await signedIn.storageState().catch(() => undefined) : existsSync(file) ? file : undefined
    const open = (s?: typeof state) => browser.newContext({ ...(device ? devices[DEVICE_PRESETS[device]] : {}), permissions: ['microphone'], ...(s ? { storageState: s } : {}) })
    const c = await openSaved(open, state, file)
    if (device) c.on('page', (p) => {
      pageDevice.set(p, device)
      p.once('close', () => {
        if (c.pages().some((x) => x !== p && !x.isClosed())) return
        if (deviceContexts.get(id) === c) deviceContexts.delete(id)
        void c.close().catch(() => {})
        mark(`${device} device context closed (last tab gone)`)
      })
    })
    await prepareContext(c); trackContext(c, key); owned.set(id, c)
    mark(device ? `${device} device context opened (${DEVICE_PRESETS[device]})` : `profile opened${state ? ' (restored cookies + localStorage)' : ''}`)
    return c
  }
  // Cookies and localStorage (where most sites, Supabase included, keep a sign-in); IndexedDB is not kept.
  let ending = false  // set once a graceful end begins
  const profileSaver = serialSaver(async () => {
    for (const [key, c] of contexts) {
      // Bounded: one wedged tab must not stall the queue and lose the shutdown save.
      const st = await withTimeout(c.storageState(), 5000, 'storageState').catch(() => null)
      if (st) try { writeAtomic(profileFile(key), JSON.stringify(st)) } catch { /* volume full or gone: keep the last file */ }
    }
  }, () => ending)
  const saveProfiles = profileSaver.now
  setInterval(profileSaver.tick, 60000)
  let active: Page = await context.newPage()
  // DEVTOOLS SENSE per tab — console, page errors, failed network, websocket
  // lifecycle. Every task response carries the active tab's summary so the
  // DIRECTOR reviews debug state alongside the media before deciding the next
  // step; GET /logs serves the full buffers; devtools.txt persists per run.
  // Late-bound so watchPage (defined early) can emit webhooks (wired later).
  let notifyRef: (event: string, payload?: Record<string, unknown>) => void = () => {}
  const devtoolsBufs = new Map<Page, DevtoolsBuffer>()
  // Per-tab last-use for the staleness sweep (touched by act/say/eval/tab ops).
  const tabLastUsed = new Map<Page, number>()
  const touchTab = (p: Page) => tabLastUsed.set(p, Date.now())
  // MB the machine can still give out (on Linux freemem() is MemAvailable); null
  // elsewhere — macOS counts only unused pages, which would close tabs needlessly.
  const freeMemoryMb = (): number | null => process.platform === 'linux' ? Math.round(freemem() / 1048576) : null
  const watchPage = (p: Page) => {
    if (devtoolsBufs.has(p)) return
    devtoolsBufs.set(p, attachDevtools(p))
    touchTab(p)
    // Browser events → webhooks: navigations ("the browser got forwarded")
    // and page errors, tagged with the tab they happened on.
    p.on('framenavigated', (f) => { if (f === p.mainFrame()) notifyRef('navigation', { url: f.url(), tab: allPages().indexOf(p) }) })
    p.on('pageerror', (e) => notifyRef('page_error', { message: redactDiagnostics(e.message).slice(0, 300), tab: allPages().indexOf(p) }))
    // Meeting/agent activity → first-class events: the frontend logs its data
    // messages to console; promote transcripts and agent output so directors
    // detect activity on ONE stream instead of tailing three log sources.
    p.on('console', (m) => {
      const t = m.text()
      // Redact before cutting: a token cut short no longer looks like one to notify()'s redaction.
      if (/Meeting transcript|user_transcript/i.test(t)) notifyRef('transcript', { text: redactDiagnostics(t).slice(0, 250), tab: allPages().indexOf(p) })
      else if (t.includes('claude_output')) notifyRef('agent_output', { text: redactDiagnostics(t).slice(0, 200), tab: allPages().indexOf(p) })
    })
  }
  const writeDevtoolsFile = () => {
    try {
      const dump = allPages().map((p, i) => {
        const b = devtoolsBufs.get(p)
        return b ? `===== TAB ${i} — ${redactDiagnostics(p.url())}\n--- console\n${b.console.join('\n')}\n--- network\n${b.network.join('\n')}` : ''
      }).filter(Boolean).join('\n\n')
      writeFileSync(join(RUN_DIR, 'devtools.txt'), dump)
    } catch { /* ignore */ }
  }
  watchPage(active)
  await installReactiveMic(active)
  await installActionVisualizer(active)
  if (!live) live = await startLiveStream(active).catch(() => null)
  manifest.live = live?.url ?? null
  manifest.captureMode = FULL_WINDOW ? 'display (full browser window)' : 'page (CDP)'
  mark(`browser up (${useAuth ? 'auth' : 'guest'}${IN_CONTAINER ? ', container' : ''}, capture: ${FULL_WINDOW ? 'full-window' : 'page'}) — live: ${live?.url ?? 'n/a'}`)
  // Load speech code and look up its provider now; the logged time shows a cold synthesis (#206).
  void warmUpSpeech().then((w) => mark(`speech warm-up: ${w.provider} in ${w.ms}ms`)).catch((e) => mark(`speech warm-up failed: ${String(e).slice(0, 80)}`))

  // BRAIN — re-initializable in place. A double page reload detaches Stagehand
  // ("uninitialized Stagehand object") and previously killed /act for the rest
  // of the session; now POST /brain rebuilds it over the same CDP endpoint.
  let stagehand: Stagehand | null = null
  let brainAlive = false
  // WHY the brain is down (missing key, bad key, CDP attach failure) — carried
  // on /status and every refused /act so a director never has to guess.
  let brainError: string | null = null
  // BRAIN PROVIDER FALLBACK (ported from b8dd898 on
  // fix/engine-voice-deepgram-gemini): a single depleted key (Gemini prepay
  // ran dry, 402) must not leave the engine brainless. Probe each configured
  // key with a 1-token real completion and build the brain on the first
  // provider that answers: Gemini → Anthropic → z.ai (Anthropic-compatible).
  // Keys travel in headers, never in a URL, so a failed probe can't leak one
  // into a log line.
  let brainModel = ''
  const pickBrainModel = async (): Promise<{ model: string; opts: Record<string, string> }> => {
    const tried: string[] = []
    const post = (url: string, headers: Record<string, string>, body: unknown) =>
      fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, body: JSON.stringify(body), signal: AbortSignal.timeout(15000) }).catch(() => null)
    const probe = async (name: string, url: string, headers: Record<string, string>, body: unknown): Promise<boolean> => {
      const r = await post(url, headers, body)
      if (r?.ok) return true
      tried.push(`${name} ${r ? r.status : 'network'}`)
      mark(`brain: ${name} probe failed (${r ? r.status : 'network'}) — trying next provider`)
      return false
    }
    const anthropicBody = (model: string) => ({ model, max_tokens: 1, messages: [{ role: 'user', content: 'ok' }] })
    const g = optionalEnvKey('GOOGLE_API_KEY') || optionalEnvKey('GEMINI_API_KEY')
    if (g) {
      // A retired model answers 404 (named in brainError so /status shows it); 401/402/429 go to the next provider.
      const picked = await pickGeminiModel(async (m) => {
        const r = await post(`https://generativelanguage.googleapis.com/v1beta/models/${m}:generateContent`, { 'x-goog-api-key': g },
          { contents: [{ parts: [{ text: 'ok' }] }], generationConfig: { maxOutputTokens: 1 } })
        return r ? r.status : null
      })
      if (picked.model) return { model: `google/${picked.model}`, opts: { apiKey: g } }
      tried.push(...picked.tried)
      mark(`brain: ${picked.tried.join(', ')} — trying next provider`)
    }
    const a = optionalEnvKey('ANTHROPIC_API_KEY')
    if (a && await probe('anthropic', 'https://api.anthropic.com/v1/messages', { 'x-api-key': a, 'anthropic-version': '2023-06-01' }, anthropicBody('claude-haiku-5-5')))
      return { model: 'anthropic/claude-haiku-5-5', opts: { apiKey: a } }
    const z = optionalEnvKey('Z_AI_API_KEY') || optionalEnvKey('ZAI_API_KEY')
    if (z && await probe('z.ai', 'https://api.z.ai/api/anthropic/v1/messages', { 'x-api-key': z, 'anthropic-version': '2023-06-01' }, anthropicBody('glm-4.7')))
      return { model: 'anthropic/glm-4.7', opts: { apiKey: z, baseURL: 'https://api.z.ai/api/anthropic/v1' } }
    throw new Error(tried.length ? `no working brain key — ${tried.join(', ')}` : 'no brain key — set GOOGLE_API_KEY (or GEMINI_API_KEY), ANTHROPIC_API_KEY or Z_AI_API_KEY')
  }
  // TEST SEAM: OSBORN_BRAIN_STUB=1 swaps the brain for one that "acts" by
  // doing nothing. It exists to exercise everything AROUND the brain — effect
  // detection, warnings, the scroll fallback, clips — without a model key.
  const BRAIN_STUB = process.env.OSBORN_BRAIN_STUB === '1'
  const initBrain = async () => {
    brainAlive = false
    if (BRAIN_STUB) { brainAlive = true; brainError = null; brainModel = 'stub (does nothing)'; mark('brain STUB active — /act performs no action'); return }
    try {
      const picked = await pickBrainModel()
      const version: any = await fetch(`http://127.0.0.1:${CDP_PORT}/json/version`, { signal: AbortSignal.timeout(5000) }).then((r) => r.json())
      if (picked.model.startsWith('google/')) process.env.GOOGLE_GENERATIVE_AI_API_KEY = picked.opts.apiKey
      // The Anthropic-compatible path (z.ai) lost its key when only passed as
      // a client option alongside a custom baseURL ("Anthropic API key is
      // missing" on every act). The provider SDK also reads these env vars,
      // so set them for whichever Anthropic-style provider was picked.
      if (picked.model.startsWith('anthropic/')) {
        process.env.ANTHROPIC_API_KEY = picked.opts.apiKey
        if (picked.opts.baseURL) process.env.ANTHROPIC_BASE_URL = picked.opts.baseURL; else delete process.env.ANTHROPIC_BASE_URL
      }
      stagehand = new Stagehand({
        env: 'LOCAL', localBrowserLaunchOptions: { cdpUrl: version.webSocketDebuggerUrl },
        model: picked.model as any, modelClientOptions: picked.opts, verbose: 0,
      })
      // Bounded: a Stagehand init that never settles would leave every later
      // revive joined to a promise that never ends (#327).
      const sh = stagehand
      await withTimeout(sh.init(), 60000, 'Stagehand init did not finish within 60s')
        .catch((e) => { void sh.close().catch(() => {}); throw e })
      brainAlive = true; brainError = null; brainModel = picked.model
      mark(`brain ready on ${picked.model}`)
    } catch (e) {
      brainError = ((e as Error).message || String(e)).slice(0, 200)
      throw e
    }
  }
  // A brain that can't start must NEVER take the whole engine down (it used to
  // be a fatal boot error: no control API, no stream, nothing to diagnose
  // with). Boot brainless: /eval /tab /shot /recover keep working, /act says
  // why it can't, and POST /brain retries once the key/CDP problem is fixed.
  await initBrain().catch(() => mark(`brain unavailable — ${brainError} — engine still drivable (/eval /tab /shot); POST /brain to retry`))
  // Speech-to-text key health, checked at boot and on POST /brain (#151).
  type SttHealth = { provider: string; ok: boolean; status: number | string }
  let sttHealth: SttHealth[] = []
  const probeStt = async () => {
    const out: SttHealth[] = []
    const check = async (provider: string, url: string, headers: Record<string, string>) => {
      try { const r = await fetch(url, { headers, signal: AbortSignal.timeout(10000) }); out.push({ provider, ok: r.ok, status: r.status }) }
      catch (e) { out.push({ provider, ok: false, status: String((e as Error).message).slice(0, 60) }) }
    }
    const sx = optionalEnvKey('SONIOX_API_KEY'); if (sx) await check('soniox', 'https://api.soniox.com/v1/files?limit=1', { Authorization: `Bearer ${sx}` })
    const dg = optionalEnvKey('DEEPGRAM_API_KEY'); if (dg) await check('deepgram', 'https://api.deepgram.com/v1/projects', { Authorization: `Token ${dg}` })
    sttHealth = out
    const bad = out.filter((h) => !h.ok)
    mark(out.length ? `ears: ${out.map((h) => `${h.provider} ${h.ok ? 'ok' : `FAILED (${h.status})`}`).join(', ')}` : 'ears: no speech-to-text key configured — /say and /hear cannot transcribe')
    if (out.length && bad.length === out.length) notify('stt_unavailable', { providers: out })
  }
  void probeStt()
  // Re-init a detached brain in place. Single-flight until the init settles (the
  // init itself is bounded). /act's automatic try (inside the action lock) starts
  // a revive and waits at most 20s for it; an /act that finds one already running
  // does not wait, and after a failure none starts another for a minute. Waiting
  // out the 20s is not a failure: the revive keeps going and its own result counts.
  let reviveFailedAt = 0
  let reviving: Promise<boolean> | null = null
  // One stuck command (a mouth whose voice services all hang, a page that never
  // settles) must not freeze every driver: after LOCK_MAX_MS the next command
  // may start, while the caller still waits for its own result.
  const LOCK_MAX_MS = Number(process.env.OSBORN_LOCK_MAX_MS) > 0 ? Number(process.env.OSBORN_LOCK_MAX_MS) : 240000
  // A timed-out brain call is waited for up to SETTLE_MS inside its own command;
  // one still running after that (its brain not yet closed) is a zombie the next
  // brain call or re-init waits out, for what is left of its command's action
  // lock (#421). One older than two lock spans is dropped, so it cannot wedge the brain.
  const SETTLE_MS = 15000
  const zombies = zombieGate({
    maxAgeMs: 2 * LOCK_MAX_MS,
    onDrop: (age) => mark(`brain: no longer waiting for a timed-out act still unsettled after ${Math.round(age / 1000)}s — it may still act`),
  })
  let lockDeadline = 0  // when the command holding the action lock may be overtaken; 0 outside the lock
  const zombieBudget = () => lockDeadline ? lockDeadline - Date.now() : SETTLE_MS
  const reviveBrain = async (auto = false): Promise<boolean> => {
    if (reviving && auto) return false  // another request is reviving: fail fast, keep the lock free
    if (!reviving) {
      if (auto && Date.now() - reviveFailedAt < 60000) return false
      reviving = (async () => {
        // A new brain must not start on a page a timed-out call may still act on (#421).
        try { await zombies.wait(zombieBudget(), 'brain re-init') }
        catch (e) { brainError = (e as Error).message; reviveFailedAt = Date.now(); mark(brainError); reviving = null; return false }
        if (stagehand) await withTimeout(stagehand.close(), 10000, 'close').catch(() => {})  // a hung close must not stall the revive
        try { await initBrain(); reviveFailedAt = 0; mark('brain re-initialized'); return true }
        catch { reviveFailedAt = Date.now(); mark(`brain re-init failed — ${brainError}`); return false }
        finally { reviving = null }
      })()
    }
    if (!auto) return reviving
    return withTimeout(reviving, 20000, 'still reviving').catch(() => false)
  }
  const brainDownMsg = () => reviving && zombies.pending ? 'a timed-out brain call is still running; the brain re-init is waiting for it to stop — retry shortly; /eval, /tab and /shot still work'
    : reviving ? 'the brain is re-initializing — retry in a few seconds; /eval, /tab and /shot still work'
    : `brain unavailable — ${brainError ?? 'detached'}. POST /brain to re-init; /eval, /tab and /shot still work`
  // `run` swaps the call under the fence (the vision retry); the default is the cached act.
  const brain = async (i: string, p: Page = active, run?: (sh: Stagehand, signal: AbortSignal) => Promise<Awaited<ReturnType<typeof actWithCache>> & { ran?: boolean; note?: string }>, maxMs?: number) => {
    if (BRAIN_STUB) return { cached: false, healed: false, did: 'stub: no action performed' }
    await zombies.wait(zombieBudget(), 'act')
    if (!stagehand || !brainAlive) throw new Error(brainDownMsg())
    // A value below 10s (say "120", meant as seconds) would time every act out at once.
    const BRAIN_TIMEOUT_MS = Number(process.env.OSBORN_BRAIN_TIMEOUT_MS) >= 10000 ? Number(process.env.OSBORN_BRAIN_TIMEOUT_MS) : 120000
    // A timed-out call is fenced (#174, #421): the abort stops it starting any action or writing
    // the action cache, its brain is closed and the lock held until both the call and the close
    // have finished (up to SETTLE_MS), and a call still running then is a zombie the next brain
    // call waits out. Stagehand 3.7's act/observe take no abort signal, so closing is the stop.
    const sh = stagehand
    const why = `brain call timed out after ${BRAIN_TIMEOUT_MS / 1000}s`
    const q = `"${i.slice(0, 60)}"`
    try {
      return await fencedCall((signal) => run ? run(sh, signal) : actWithCache(sh, p, i, signal), {
        timeoutMs: maxMs ? Math.min(BRAIN_TIMEOUT_MS, maxMs) : BRAIN_TIMEOUT_MS, settleMs: SETTLE_MS, why,
        onTimeout: (call) => {
          // A replacement brain has its own CDP connection; the revive that made it closed this one.
          if (stagehand !== sh) { zombies.track(call); return }
          brainAlive = false; brainError = why
          const closing = sh.close()
          zombies.track(call, closing)  // once closed, its connection is gone and it cannot act
          return closing
        },
        settled: (end, closed) => {
          if (end === 'running') mark(`brain: a timed-out act was still running ${SETTLE_MS / 1000}s after the deadline — the next brain call waits for it and is refused if it does not stop: ${q}`)
          if (!closed) mark(`brain: closing the timed-out brain did not finish within ${SETTLE_MS / 1000}s: ${q}`)
        },
        onLate: (l) => {
          if ('error' in l) mark(`brain: a timed-out act failed late, possibly after acting (${String((l.error as Error)?.message ?? l.error).slice(0, 100)}): ${q}`)
          else if (!l.value.noop) mark(`brain: a timed-out act finished late and acted (${l.value.did ?? 'unknown action'}), not cached: ${q}`)
        },
      })
    }
    catch (e) {
      if (BRAIN_GONE.test(String(e))) { brainAlive = false; brainError = 'detached from the browser'; mark('brain detached — POST /brain to re-init') }
      throw e
    }
  }

  const chatUrl = `${APP_URL}/chat?provider=gemini&voiceArch=pipeline&agent=claude&agentUrl=${encodeURIComponent(AGENT_URL)}`
  const url = useAuth ? `${APP_URL}/dashboard` : chatUrl
  // BOOT ORDER (v8): the room join happens in the BACKGROUND, after the
  // control server is listening. A wedged "Connecting..." must never leave
  // the engine headless — 2026-07-31 a platform-side guest-connect regression
  // did exactly that: no /status, no /shot, no way to see or steer the boot.
  let tCapture = Date.now()
  let roomReady = false
  // True only after the voice-room join actually succeeded (NOT for
  // OSBORN_ENTRY=none or the agent-unreachable neutral page).
  let joinedRoom = false
  // AGENT REACHABILITY (#49): null while the configured agent is reachable (or
  // before a join is attempted); set to a short "agent unreachable: <host>"
  // reason when the boot chat can't be joined, so /status and the live view say
  // WHY instead of the chat spinning on "Connecting…" forever.
  let agentUnreachable: string | null = null

  // Every reply, event and webhook is redacted like the public logs (#328); in-memory records and the journey restart state stay raw for replay.
  // A reply already sent (an open command answered on SIGTERM, #324) is never written twice.
  const json = (res: any, body: any, code = 200, raw = false) => { if (res.headersSent) return; res.writeHead(code, { 'Content-Type': 'application/json' }); res.end(raw ? JSON.stringify(body) : redactJson(body)) }
  // goto with a clean error: 400 for a bad URL, 502 for a failed load (no ANSI codes),
  // and no error when the tab reached the page anyway (an interrupted-but-landed load).
  // Success carries redirectedTo when the tab settled on another URL of the same host
  // (http→https, a trailing slash, /login → /dashboard): a redirect is not a failure (#316).
  const badUrl = (raw: unknown): { status: number; body: any } | null => {
    let u: URL
    try { u = new URL(String(raw)) } catch { return { status: 400, body: { ok: false, code: 'bad_url', error: `not a URL: ${String(raw).slice(0, 200)}` } } }
    return /^https?:$/.test(u.protocol) ? null : { status: 400, body: { ok: false, code: 'bad_url', error: 'only http(s) URLs can be opened' } }
  }
  type NavFail = { status: number; body: any }
  const gotoChecked = async (page: Page, raw: unknown): Promise<NavFail | { redirectedTo: string | null }> => {
    const bad = badUrl(raw); if (bad) return bad
    const u = new URL(String(raw))
    const noHash = (h: string) => h.split('#')[0]
    const hostOf = (h: string) => (badUrl(h) ? null : new URL(h).hostname)
    const landed = () => { const now = page.url(); return { redirectedTo: noHash(now) === noHash(u.href) ? null : now } }
    const before = noHash(page.url())
    try { await page.goto(u.href, { timeout: 45000 }); return landed() } catch (e) {
      const msg = (e as Error).message.replace(/\u001b\[[0-9;]*m/g, '').split('\n')[0]
      // An interrupted load that still reached the target, or a page of the same host it
      // redirected to (and was not already showing), is a success once navigation settles.
      await page.waitForLoadState('domcontentloaded', { timeout: 5000 }).catch(() => {})
      const now = noHash(page.url())
      if (before !== now && (now === noHash(u.href) || hostOf(now) === u.hostname)) return landed()
      return { status: 502, body: { ok: false, code: 'nav_failed', netError: (msg.match(/net::[A-Z0-9_]+/) || [null])[0], error: msg.slice(0, 300) } }
    }
  }
  const readBody = (req: any): Promise<any> => new Promise((r) => { let b = ''; req.on('data', (c: any) => b += c); req.on('end', () => { try { r(JSON.parse(b || '{}')) } catch { r({ __badJson: true }) } }) })

  let reqN = 0
