  // it as mp3 (GET /audio) and (b) mux a task's ALIGNED audio slice into its
  // video clip (GET /clip?n=N&audio=1). Alignment maps wall-clock → recording
  // time through the page's audio-clock samples (`clock`, see audio-capture):
  // the recording starts at the first tapped source, not when capture was
  // armed, and runs on the page's audio clock, which a throttled CPU slows
  // (0.37x measured on the Fly engine). The samples are taken in the page, so
  // the time spent copying the recording out does not skew them.
  // `page` defaults to the active tab; callers outside the action lock must
  // pass the tab they mean. Temp files are per call (two muxes used to share
  // `_peek.*` and could read each other's half-written audio).
  let peekSeq = 0
  const peekAudioToWav = async (page: Page = active, maxMs = AUDIO_DECODE_CAP_MS): Promise<{ wav: string; clock: AudioClock; durationMs: number } | null> => {
    let cleanup: string[] = []
    try {
      const { bytes, sinceStartMs, clock } = await peekCapture(page)
      if (!bytes.length) return null
      // Decoding the whole recording on every turn does not scale (a 2h
      // capture is ~30s of ffmpeg and ~700MB of wav). Past the cap, proof
      // clips go without the page-audio track rather than stall every /say.
      if (sinceStartMs > maxMs) { mark(`page-audio track skipped — recording is ${Math.round(sinceStartMs / 60000)}min long`); return null }
      const id = ++peekSeq
      const webm = join(RUN_DIR, `_peek-${id}.webm`)
      writeFileSync(webm, bytes)
      const wav = join(RUN_DIR, `_peek-${id}.wav`)
      cleanup = [webm, wav]
      // Full decode → wav: MediaRecorder opus can't be seeked directly (bad
      // packet headers — proven), so decode once and trim the wav reliably.
      await execFileP('ffmpeg', ['-y', '-loglevel', 'error', '-i', webm, '-c:a', 'pcm_s16le', '-ar', '48000', wav], { timeout: 30000 })
      const probe = await execFileP('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', wav], { timeout: 10000 }).catch(() => ({ stdout: '0' }))
      cleanup = [webm]
      return { wav, clock, durationMs: Math.round((Number(String(probe.stdout).trim()) || 0) * 1000) }
    } catch { return null }
    finally { for (const f of cleanup) try { rmSync(f, { force: true }) } catch { /* ignore */ } }
  }
  // Only a recording that overlaps the clip gives it sound: a seek past the
  // end muxes silence, which must not be reported as page audio.
  const overlapsClip = (a: { clock: AudioClock; durationMs: number }, startMs: number, endMs: number) =>
    recordingMsAt(a.clock, startMs) < a.durationMs - 100 && recordingMsAt(a.clock, endMs) > 0
  const muxClipAudio = async (videoPath: string, endMs: number, n: number, page: Page = active): Promise<string | null> => {
    const a = await peekAudioToWav(page)
    if (!a) return null
    try {
      const probe = await execFileP('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', videoPath])
      const dur = Math.max(1, Number(String(probe.stdout).trim()) || 14)
      // Clip video spans ~[endMs - dur, endMs] in wall-clock; map to recording time.
      // Recording started after the clip did (ears armed during the action):
      // delay the audio by the gap instead of pulling it to the clip's start.
      const offset = recordingMsAt(a.clock, endMs - dur * 1000) / 1000
      if (!overlapsClip(a, endMs - dur * 1000, endMs)) return null
      // Only what was recorded during the clip: on a slow audio clock the clip's
      // span is shorter in the recording, so later audio must not run on into it.
      const span = Math.max(0, recordingMsAt(a.clock, endMs) / 1000 - Math.max(0, offset))
      const seek = offset >= 0 ? ['-ss', String(offset), '-t', span.toFixed(3)] : ['-itsoffset', String(-offset), '-t', span.toFixed(3)]
      const out = join(RUN_DIR, `req-${String(n).padStart(3, '0')}-withaudio.mp4`)
      await execFileP('ffmpeg', ['-y', '-loglevel', 'error', '-i', videoPath, ...seek, '-i', a.wav,
        // apad: silence after the recorded span, so -shortest keeps the clip's full video.
        '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-af', 'apad', '-c:a', 'aac', '-b:a', '128k', '-shortest', out])
      return existsSync(out) ? out : null
    } catch { return null }
    finally { try { rmSync(a.wav, { force: true }) } catch { /* ignore */ } }
  }
  // EARS ON ANY TAB. Page-audio capture used to be armed only by the boot
  // room-join on tab 0, so a voice session in any other tab was deaf: /say
  // "succeeded" with an empty transcript and /hear threw. The ears now arm
  // themselves on whichever tab is spoken to or listened on, and every answer
  // says what state they were in, so "the agent was silent" can be told apart
  // from "nobody was listening".
  // `heardSince`: did the ears detect sound (speech-start, or still sounding)
  // since that time? `tapped`: was any page audio source ever recorded?
  const earsState = async (p: Page, since = 0): Promise<{ armed: boolean; startedAt: number | null; audioElements: number; playing: number; tapped?: boolean; heardSince?: boolean; audioClock?: number | null }> =>
    (await Promise.race([
      p.evaluate((since) => {
        const g = globalThis as any
        const c = g.__osbornCapture
        const els = [...document.querySelectorAll('audio,video')] as HTMLMediaElement[]
        const ev: Array<{ type: string; t: number }> = g.__osbornEars ?? []
        const last = ev[ev.length - 1]
        return { armed: !!c, startedAt: c?.startedAt ?? null, audioElements: els.length, playing: els.filter((e) => !e.paused && (e.srcObject || e.currentSrc)).length,
          tapped: !!g.__osbornAudioAnchor, heardSince: ev.some((e) => e.type === 'speech-start' && e.t >= since) || last?.type === 'speech-start',
          audioClock: g.__osbornClock?.rate?.() ?? null }
      }, since),
      new Promise<null>((r) => setTimeout(() => r(null), 3000)),
    ]).catch(() => null)) ?? { armed: false, startedAt: null, audioElements: 0, playing: 0, unknown: true }
  const ensureEars = async (p: Page) => {
    const before = await earsState(p) as Awaited<ReturnType<typeof earsState>> & { unknown?: boolean }
    // A page too busy to answer is NOT "unarmed": arming again would replace
    // the existing recording and orphan its recorder. Only arm on a clear no.
    if (before.armed || before.unknown) return { ...before, armedNow: false }
    await startElementCapture(p).catch(() => {})
    return { ...(await earsState(p)), armedNow: true }
  }
  // AUDIBLE PROOF for a spoken turn: the true-time video clip plus BOTH sides
  // of the audio — what the tester said (the synthesized utterance, placed at
  // the instant it was played into the mic) and what the page played back
  // (the ears' recording, aligned through its audio clock). Returns null when there is
  // no audio at all to add.
  const muxSayAudio = async (clip: { path: string; startMs: number; endMs: number }, saidWav: string | null, playStartMs: number, n: number, captions: { said: string; heard: string }, a: Awaited<ReturnType<typeof peekAudioToWav>>, timeoutMs = 45000): Promise<{ path: string; said: boolean; heard: boolean } | null> => {
    const args = ['-y', '-loglevel', 'error', '-i', clip.path]
    const filters: string[] = []; const labels: string[] = []
    let idx = 1
    const said = !!saidWav && existsSync(saidWav) && playStartMs > 0
    if (said) {
      const d = Math.round(playStartMs - clip.startMs)
      // d < 0: the clip starts AFTER the utterance began (a turn longer than
      // the frame buffer) — skip that much of the wav instead of pinning the
      // whole utterance to the start of the clip.
      if (d < 0) args.push('-ss', (-d / 1000).toFixed(3))
      args.push('-i', saidWav!); filters.push(`[${idx}:a]aresample=48000${d > 0 ? `,adelay=${d}:all=1` : ''}[s]`); labels.push('[s]'); idx++
    }
    // `a` is the recording the caller decoded once for this turn; the caller deletes it.
    const off = a ? recordingMsAt(a.clock, clip.startMs) / 1000 : 0
    const heard = !!a && overlapsClip(a, clip.startMs, clip.endMs)
    if (a && heard) {
      if (off >= 0) args.push('-ss', off.toFixed(3))
      args.push('-t', Math.max(0, recordingMsAt(a.clock, clip.endMs) / 1000 - Math.max(0, off)).toFixed(3))  // nothing recorded after the clip
      args.push('-i', a.wav)
      filters.push(`[${idx}:a]aresample=48000${off < 0 ? `,adelay=${Math.round(-off * 1000)}:all=1` : ''}[h]`); labels.push('[h]'); idx++
    }
    if (!labels.length) return null
    const out = join(RUN_DIR, `req-${String(n).padStart(3, '0')}-say-av.mp4`)
    // Bounded: an unbounded apad never ends once video is re-encoded.
    const clipDur = Math.max(1, (clip.endMs - clip.startMs) / 1000)
    // Players autoplay muted, so the clip SHOWS its sound: waveform + captions.
    // loudnorm resamples to 192kHz: back to 48kHz, or the waveform and AAC encode work on 4x the samples.
    filters.push(`${labels.join('')}amix=inputs=${labels.length}:normalize=0:duration=longest,apad=whole_dur=${clipDur.toFixed(3)},atrim=0:${clipDur.toFixed(3)},loudnorm=I=-18:TP=-2,aformat=sample_rates=48000:channel_layouts=stereo,asplit=2[a][aw]`)
    // Same width as the clip (OSBORN_CLIP_WIDTH): this re-encode is the costliest step of a turn.
    const W = Number(process.env.OSBORN_CLIP_WIDTH ?? 640), k = W / 1280, px = (v: number) => Math.round(v * k)
    const WAVE_H = px(90) & ~1
    filters.push(`[aw]showwaves=s=${W}x${WAVE_H}:mode=cline:colors=0x46d38a,format=rgba,colorchannelmixer=aa=0.85[wav]`)
    let vchain = `[0:v]scale=${W}:-2,pad=${W}:ih+${WAVE_H}:0:0:black[base];[base][wav]overlay=0:H-${WAVE_H}:shortest=1`
    const capFiles: string[] = []
    if (captions) {
      const saidAt = said ? Math.max(0, (playStartMs - clip.startMs) / 1000) : 0
      const saidFor = said ? Math.max(1.5, (await execFileP('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', saidWav!]).then((r) => Number(String(r.stdout).trim()) || 3).catch(() => 3))) : 0
      const box = `box=1:boxcolor=black@0.65:boxborderw=${px(10)}:fontcolor=white:fontsize=${Math.max(12, px(24))}:x=${px(24)}`
      // Captions are burned into a public clip: redact first (the audio track itself cannot be).
      const wrap = (t: string) => redactDiagnostics(t).replace(/\s+/g, ' ').trim().slice(0, 220).replace(/(.{1,80})(\s|$)/g, '$1\n').trim()
      const cap = (name: string, text: string) => { const f = join(RUN_DIR, `_cap-${n}-${name}.txt`); writeFileSync(f, text); capFiles.push(f); return f.replace(/\\/g, '/').replace(/:/g, '\\:') }
      if (said) vchain += `,drawtext=textfile='${cap('said', `TESTER SAID: ${wrap(captions.said)}`)}':${box}:y=${px(24)}:enable='between(t\\,${saidAt.toFixed(2)}\\,${(saidAt + saidFor).toFixed(2)})'`
      const replyFrom = said ? saidAt + saidFor : 0
      vchain += `,drawtext=textfile='${cap('heard', captions.heard ? `HEARD BACK (transcript): ${wrap(captions.heard)}` : 'NO SPEECH TRANSCRIBED in reply (any sound is still in the audio and waveform)')}':${box}:y=h-${WAVE_H}-${px(24)}-th:enable='gte(t\\,${replyFrom.toFixed(2)})'`
